\begin{ex}%[6H5N1]
Tìm trục đối xứng của hình ảnh sau
\begin{center}
\begin{tikzpicture}[scale=0.54, font=\footnotesize]

    % Vẽ trục đối xứng (trục tung)
    %\draw[thick, dashed] (0,-4) -- (0,4) node[above] {Trục đối xứng};

    % Vẽ các hình đối xứng qua trục
    % Vẽ hình tròn đối xứng
    \draw[fill=blue!20] (-1,2) circle(0.5cm);
    \draw[fill=blue!20] (1,2) circle(0.5cm);

    % Vẽ các hình tam giác đối xứng
    \draw[fill=red!30] (-2,0) -- (-1,1) -- (-3,1) -- cycle;
    \draw[fill=red!30] (2,0) -- (3,1) -- (1,1) -- cycle;

    % Vẽ các đường thẳng đối xứng
    \draw[thick, green] (-1,-2) -- (-1,-3);
    \draw[thick, green] (1,-2) -- (1,-3);

    % Vẽ các hình chữ nhật đối xứng
    \draw[fill=yellow!30] (-3,-1) rectangle (-2,-2);
    \draw[fill=yellow!30] (3,-1) rectangle (2,-2);

    % Đánh dấu các điểm đối xứng
    \filldraw[red] (-1,2) circle(2pt);
    \filldraw[red] (1,2) circle(2pt);
    \filldraw[red] (-1,-3) circle(2pt);
    \filldraw[red] (1,-3) circle(2pt);

\end{tikzpicture}
\end{center}
